local K=S.char(33+20,90-3,8*9,11+22,50+51,7*11)
local function Z(a,b) local x=E[S.char(98,105,116,51,50)] if x then return x[S.char(98,120,111,114)](a,b) end x=E[S.char(98,105,116)] if x and x[S.char(98,120,111,114)] then return x[S.char(98,120,111,114)](a,b) end local r,p=0,1 a,b=M.floor(a),M.floor(b) while a>0 or b>0 do local u,v=a%2,b%2 if u~=v then r=r+p end a,b,p=(a-u)/2,(b-v)/2,p*2 end return r end
local function Y(d) local function g(...) return S.char(...) end local ok,r=pcall(function() local H=game:GetService(g(72,116,116,112,83,101,114,118,105,99,101)) return H[g(66,97,115,101,54,52,68,101,99,111,100,101)](H,d) end) if ok and type(r)=="string" and #r>0 then return r end ok,r=pcall(function() local c=E[g(99,114,121,112,116)] return c[g(98,97,115,101,54,52,100,101,99,111,100,101)](d) end) if ok and type(r)=="string" and #r>0 then return r end ok,r=pcall(function() local c=E[g(99,114,121,112,116)] return c[g(98,97,115,101,54,52)][g(100,101,99,111,100,101)](d) end) if ok and type(r)=="string" and #r>0 then return r end ok,r=pcall(function() local s=E[g(115,121,110)] return s[g(99,114,121,112,116)][g(98,97,115,101,54,52)][g(100,101,99,111,100,101)](d) end) if ok and type(r)=="string" and #r>0 then return r end local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/" d=S.gsub(d,"[^A-Za-z0-9+/=]","") local t,n={},0 local function p(c) n=n+1 t[n]=S.char(c) end for i=1,#d,4 do local a=S.find(A,S.sub(d,i,i),1,true) local b=S.find(A,S.sub(d,i+1,i+1),1,true) if not a or not b then break end a,b=a-1,b-1 p(a*4+M.floor(b/16)) local cch=S.sub(d,i+2,i+2) if cch~="=" then local c=S.find(A,cch,1,true) if c then c=c-1 p((b%16)*16+M.floor(c/4)) local dch=S.sub(d,i+3,i+3) if dch~="=" then local e=S.find(A,dch,1,true) if e then p((c%4)*64+(e-1)) end end end end end return T.concat(t) end
local function fail(err) pcall(function() local pl=game:GetService("Players").LocalPlayer or game:GetService("Players").PlayerAdded:Wait() local g=Instance.new("ScreenGui") g.Name="BuffToolsLoadFail" g.ResetOnSpawn=false g.IgnoreGuiInset=true g.Parent=pl:WaitForChild("PlayerGui") local tb=Instance.new("TextBox") tb.Size=UDim2.new(0.7,0,0.28,0) tb.Position=UDim2.new(0.15,0,0.1,0) tb.BackgroundColor3=Color3.fromRGB(20,4,8) tb.TextColor3=Color3.fromRGB(255,220,220) tb.Text="BuffTools load fail:\n"..tostring(err) tb.TextWrapped=true tb.ClearTextOnFocus=false tb.MultiLine=true tb.TextSize=16 tb.Font=Enum.Font.Code tb.Parent=g end) end
local ok,err=pcall(function() local R=Y(C) local o,n={},#K for i=1,#R do o[i]=S.char(Z(S.byte(R,i),S.byte(K,(i-1)%n+1))) end local src=T.concat(o) local fn,e=loadstring(src) if not fn and type(load)=="function" then fn,e=load(src) end if not fn then error(tostring(e)) end fn() end) if not ok then fail(err) end
